class Solution {
public:
    string bestHand(vector<int>& ranks, vector<char>& suits) {
        bool flush = true;
        for (char c : suits) if (c != suits[0]) flush = false;
        if (flush) return "Flush";
        int cnt[14] = {};
        for (int r : ranks) cnt[r]++;
        int m = *max_element(cnt, cnt + 14);
        if (m >= 3) return "Three of a Kind";
        if (m == 2) return "Pair";
        return "High Card";
    }
};

