class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        boolean flush = true;
        for (char c : suits) if (c != suits[0]) flush = false;
        if (flush) return "Flush";
        int[] cnt = new int[14];
        for (int r : ranks) cnt[r]++;
        int m = 0;
        for (int c : cnt) m = Math.max(m, c);
        if (m >= 3) return "Three of a Kind";
        if (m == 2) return "Pair";
        return "High Card";
    }
}

