var bestHand = function(ranks, suits) {
    if (new Set(suits).size === 1) return "Flush";
    const cnt = {};
    for (const r of ranks) cnt[r] = (cnt[r] || 0) + 1;
    const m = Math.max(...Object.values(cnt));
    if (m >= 3) return "Three of a Kind";
    if (m === 2) return "Pair";
    return "High Card";
};
